class IamV1Alpha1UnauthenticatedAPI:
    """
    Unauthenticated API
    """

    def __init__(self, client: ScalewayClient) -> None:
        self._client = client

    async def initiate_magic_code_login(
        self,
        *,
        organization_id: str | None = None,
        username: str | None = None,
    ) -> None:
        """
        Initiate a Magic Code login attempt and send an email with the code to the user

        Args:
            organization_id: The UUID of the organization on which to login.
            username: The username of the user that logs in.
        """
        await self._client.request(
            "POST",
            "/iam/v1alpha1/initiate-magic-code-login",
            body={
                "organization_id": self._client.organization_id(organization_id),
                "username": username,
            },
        )

    async def initiate_o_auth2_login(
        self,
        *,
        organization_id: str | None = None,
        identity_provider: OAuth2IdentityProvider | None = None,
        local_redirect_uri: str | None = None,
        remote_redirect_uri: str | None = None,
    ) -> InitiateOAuth2LoginResponse:
        """
        Args:
            organization_id: The UUID of the organization on which to login.
            identity_provider: Identity provider to connect with.
            local_redirect_uri: URI to redirect to after login.
            remote_redirect_uri: URI to which the identity provider will redirect after
                the authentication phase.
        """
        data = await self._client.request_json(
            "POST",
            "/iam/v1alpha1/initiate-oauth2-login",
            body={
                "organization_id": self._client.organization_id(organization_id),
                "identity_provider": identity_provider,
                "local_redirect_uri": local_redirect_uri,
                "remote_redirect_uri": remote_redirect_uri,
            },
        )
        return InitiateOAuth2LoginResponse.model_validate(data)

